using System.Security.Claims;
using Microsoft.AspNetCore.Components.Authorization;

namespace sv_26020ccc566b41c789483eccdbe0412d.Auth;

/// <summary>
/// Server-side AuthenticationStateProvider that simulates a logged-in user.
/// </summary>
public class FakeAuthenticationStateProvider : AuthenticationStateProvider
{
    public override Task<AuthenticationState> GetAuthenticationStateAsync()
    {
        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, "bob@example.com"),
            new(ClaimTypes.Email, "bob@example.com"),
            new(ClaimTypes.Role, "User"),
            new(ClaimTypes.Role, "Editor"),
        };

        var identity = new ClaimsIdentity(claims, "FakeAuth");
        var user = new ClaimsPrincipal(identity);

        return Task.FromResult(new AuthenticationState(user));
    }
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;

namespace sv_26020ccc566b41c789483eccdbe0412d.Auth;

/// <summary>
/// Persists the authentication state so it survives the Server→WebAssembly transition.
/// Runs only on the server and serializes claims into PersistentComponentState.
/// </summary>
public class PersistingServerAuthenticationStateProvider : AuthenticationStateProvider, IHostEnvironmentAuthenticationStateProvider, IDisposable
{
    private readonly PersistentComponentState _persistentComponentState;
    private readonly PersistingComponentStateSubscription _subscription;
    private Task<AuthenticationState>? _authenticationStateTask;

    public PersistingServerAuthenticationStateProvider(PersistentComponentState persistentComponentState)
    {
        _persistentComponentState = persistentComponentState;
        _subscription = _persistentComponentState.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    public void SetAuthenticationState(Task<AuthenticationState> authenticationStateTask)
    {
        _authenticationStateTask = authenticationStateTask;
    }

    public override async Task<AuthenticationState> GetAuthenticationStateAsync()
    {
        if (_authenticationStateTask is null)
        {
            // Fall back to the fake provider logic for initial server render
            var claims = new List<Claim>
            {
                new(ClaimTypes.Name, "bob@example.com"),
                new(ClaimTypes.Email, "bob@example.com"),
                new(ClaimTypes.Role, "User"),
                new(ClaimTypes.Role, "Editor"),
            };
            var identity = new ClaimsIdentity(claims, "FakeAuth");
            return new AuthenticationState(new ClaimsPrincipal(identity));
        }

        return await _authenticationStateTask;
    }

    private async Task OnPersistingAsync()
    {
        var authState = await GetAuthenticationStateAsync();
        var principal = authState.User;

        if (principal.Identity?.IsAuthenticated == true)
        {
            var userData = new UserData
            {
                Name = principal.FindFirst(ClaimTypes.Name)?.Value ?? "",
                Email = principal.FindFirst(ClaimTypes.Email)?.Value ?? "",
                Roles = principal.FindAll(ClaimTypes.Role).Select(c => c.Value).ToArray(),
            };

            _persistentComponentState.PersistAsJson(nameof(UserData), userData);
        }
    }

    public void Dispose()
    {
        _subscription.Dispose();
    }
}

namespace sv_26020ccc566b41c789483eccdbe0412d.Auth;

/// <summary>
/// Serializable DTO used to persist auth state across render mode transitions.
/// </summary>
public class UserData
{
    public string Name { get; set; } = "";
    public string Email { get; set; } = "";
    public string[] Roles { get; set; } = [];
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;

namespace sv_26020ccc566b41c789483eccdbe0412d.Client;

/// <summary>
/// Client-side (WebAssembly) AuthenticationStateProvider that reads
/// the persisted auth state serialized by the server during prerendering.
/// </summary>
public class PersistentAuthenticationStateProvider : AuthenticationStateProvider
{
    private static readonly Task<AuthenticationState> _unauthenticatedTask =
        Task.FromResult(new AuthenticationState(new ClaimsPrincipal(new ClaimsIdentity())));

    private readonly Task<AuthenticationState> _authenticationStateTask;

    public PersistentAuthenticationStateProvider(PersistentComponentState persistentState)
    {
        if (persistentState.TryTakeFromJson<UserData>(nameof(UserData), out var userData) && userData is not null)
        {
            var claims = new List<Claim>
            {
                new(ClaimTypes.Name, userData.Name),
                new(ClaimTypes.Email, userData.Email),
            };

            foreach (var role in userData.Roles)
            {
                claims.Add(new Claim(ClaimTypes.Role, role));
            }

            var identity = new ClaimsIdentity(claims, "PersistentAuth");
            var user = new ClaimsPrincipal(identity);
            _authenticationStateTask = Task.FromResult(new AuthenticationState(user));
        }
        else
        {
            _authenticationStateTask = _unauthenticatedTask;
        }
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync() => _authenticationStateTask;
}

